28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
35	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
37	import org.springframework.samples.petclinic.rest.advice.DisposableEmailException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
39	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.Households;
50	import org.springframework.samples.petclinic.util.Localities;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
70	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
71	     * numeric {@code membershipLevel}.
72	     */
73	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
124	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
125	        rejectFutureRegistrationDate(registrationDate);
126	        if (registrationDate == null) {
127	            registrationDate = java.time.LocalDate.now();
128	        }
129	        registrationDate = toBusinessDay(registrationDate);
130	        owner.setRegistrationDate(registrationDate);
131	        rejectDailyLimitReached(registrationDate);
132	        rejectCityAtCapacity(owner.getCity());
133	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
134	        owner.setTelephone(telephone);
135	        String email = normalizeEmail(ownerFieldsDto.getEmail());
136	        owner.setEmail(email);
137	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        rejectDuplicateIdentity(owner);
140	        rejectDuplicateHousehold(owner, sharesHousehold);
141	        String region = Localities.region(owner.getPostcode(), owner.getCity());
142	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
145	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
146	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
147	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
148	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
149	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
154	            ownerDto.getMembershipLevel());
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    /**
161	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
162	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
163	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
164	     * date, before any business-day adjustment.
165	     *
166	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
167	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
168	     */
169	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
170	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
171	            throw new FutureRegistrationDateException(registrationDate);
172	        }
173	    }
174	
175	    /**
176	     * The maximum number of owners that may be created in a single day. Creating an owner once this
177	     * many owners already carry today's {@code registrationDate} is rejected.
178	     */
179	    private static final int DAILY_OWNER_LIMIT = 100;
180	
181	    /**
182	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
183	     * given business day as their {@code registrationDate}. The count is keyed by the
184	     * business-day-adjusted registration date of the owner being created (see
185	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
186	     * with no {@code registrationDate} are ignored.
187	     *
188	     * @param registrationDate the business-day-adjusted registration date of the owner being created
189	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
190	     */
191	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
192	        long count = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
194	            .count();
195	        if (count >= DAILY_OWNER_LIMIT) {
196	            throw new DailyOwnerLimitException(registrationDate);
197	        }
198	    }
199	
200	    /**
201	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
202	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
203	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
204	     */
205	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
206	
207	    /**
208	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
209	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
210	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
211	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
212	     * owner being created is excluded (it has not yet been saved).
213	     *
214	     * @param registrationDate the business-day-adjusted registration date of the owner being created
215	     * @return {@code true} if more than the threshold of owners already carry this business day
216	     */
217	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
218	        long count = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
222	    }
223	
224	    /**
225	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
226	     * the following Monday; a weekday is returned unchanged. This applies to the effective
227	     * registration date whether it was supplied in the request or defaulted to the server date, and
228	     * every value derived from the registration date uses the adjusted result.
229	     *
230	     * @param date the effective registration date
231	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
232	     */
233	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
234	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
235	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
236	            date = date.plusDays(1);
237	        }
238	        return date;
239	    }
240	
241	    /**
242	     * The maximum number of owners a single city may contain. Creating an owner in a city that
243	     * already holds this many owners is rejected.
244	     */
245	    private static final int CITY_CAPACITY = 50;
246	
247	    /**
248	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
249	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
250	     * treated as empty).
251	     *
252	     * @param city the city of the owner being created
253	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
254	     */
255	    private void rejectCityAtCapacity(String city) {
256	        String cityValue = city == null ? "" : city;
257	        long count = this.clinicService.findAllOwners().stream()
258	            .filter(existing -> cityValue.equalsIgnoreCase(
259	                existing.getCity() == null ? "" : existing.getCity()))
260	            .count();
261	        if (count >= CITY_CAPACITY) {
262	            throw new CityAtCapacityException(city);
263	        }
264	    }
265	
266	    /**
267	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
268	     * REGION is the owner's canonical region (derived by preferring the postcode, see
269	     * {@link Localities#region(String, String)} — the same region derivation shared with the
270	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
271	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
272	     * There are no sequence numbers: the code is fully derived from the owner's own identity fields.
273	     *
274	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
275	     * @param telephone the owner's normalized (E.164) telephone
276	     * @param lastName the owner's last name
277	     * @return the assigned customer code
278	     */
279	    private String assignCustomerCode(String region, String telephone, String lastName) {
280	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
281	        String hash8 = sha256UpperHex(basis).substring(0, 8);
282	        return region + "-" + hash8;
283	    }
284	
285	    /**
286	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
287	     */
288	    private static String sha256UpperHex(String value) {
289	        try {
290	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
291	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
292	            StringBuilder sb = new StringBuilder(digest.length * 2);
293	            for (byte b : digest) {
294	                sb.append(String.format("%02X", b));
295	            }
296	            return sb.toString();
297	        }
298	        catch (java.security.NoSuchAlgorithmException e) {
299	            throw new IllegalStateException("SHA-256 not available", e);
300	        }
301	    }
302	
303	    /**
304	     * Counts how many existing owners share the given first and last name, compared
305	     * case-insensitively, at the time this owner is created. The value excludes the owner
306	     * being created (which has not yet been saved) and is stored on the new owner and returned
307	     * as its {@code namesakeCount}.
308	     *
309	     * @param firstName the first name of the owner being created
310	     * @param lastName the last name of the owner being created
311	     * @return the number of existing owners with the same first and last name
312	     */
313	    private int countNamesakes(String firstName, String lastName) {
314	        String first = firstName == null ? "" : firstName;
315	        String last = lastName == null ? "" : lastName;
316	        return (int) this.clinicService.findAllOwners().stream()
317	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
318	                && last.equalsIgnoreCase(existing.getLastName()))
319	            .count();
320	    }
321	
322	    /**
323	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
324	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
325	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
326	     * the household's size after this create is this count plus one. It is stored on the new owner.
327	     *
328	     * @param lastName the last name of the owner being created
329	     * @param postcode the postcode of the owner being created
330	     * @return the number of existing owners sharing this owner's household
331	     */
332	    private int countHouseholdMembers(String lastName, String postcode) {
333	        String householdId = Households.householdId(lastName, postcode);
334	        return (int) this.clinicService.findAllOwners().stream()
335	            .filter(existing -> householdId.equals(
336	                Households.householdId(existing.getLastName(), existing.getPostcode())))
337	            .count();
338	    }
339	
340	    /**
341	     * Rejects creating an owner that would join an existing household without opting in. The household
342	     * is keyed on the computed {@code householdId} (see {@link Households#householdId}, derived from the
343	     * normalized last name and postcode), so an owner sharing an existing owner's last name and postcode
344	     * is the same household. When another owner already belongs to that household the create is rejected,
345	     * unless the request opts in with {@code sharesHousehold}, which bypasses this block and creates the
346	     * owner as a declared household member. An owner with no postcode is never treated as a household
347	     * duplicate.
348	     *
349	     * @param owner the owner being created, with its last name and postcode already set
350	     * @param sharesHousehold whether the request opted in via {@code sharesHousehold}
351	     * @throws DuplicateHouseholdException (409 Conflict) if the owner joins an existing household and did
352	     *         not opt in
353	     */
354	    private void rejectDuplicateHousehold(Owner owner, boolean sharesHousehold) {
355	        if (sharesHousehold) {
356	            return;
357	        }
358	        String postcode = owner.getPostcode();
359	        if (postcode == null) {
360	            return;
361	        }
362	        String householdId = Households.householdId(owner.getLastName(), postcode);
363	        boolean exists = this.clinicService.findAllOwners().stream()
364	            .anyMatch(existing -> householdId.equals(
365	                Households.householdId(existing.getLastName(), existing.getPostcode())));
366	        if (exists) {
367	            throw new DuplicateHouseholdException(owner.getLastName(), postcode);
368	        }
369	    }
370	
371	    /**
372	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
373	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
374	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
375	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
376	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
377	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
378	     *
379	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
380	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
381	     */
382	    private Integer findPossibleDuplicateOf(Owner owner) {
383	        String postcode = owner.getPostcode();
384	        if (postcode == null) {
385	            return null;
386	        }
387	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
388	        String telephone = owner.getTelephone();
389	        return this.clinicService.findAllOwners().stream()
390	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
391	            .filter(existing -> postcode.equals(existing.getPostcode()))
392	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
393	            .map(Owner::getId)
394	            .filter(java.util.Objects::nonNull)
395	            .min(java.util.Comparator.naturalOrder())
396	            .orElse(null);
397	    }
398	
399	    /**
400	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
401	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
402	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
403	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
404	     * {@code "+61412345678"}. The E.164 value is stored and returned.
405	     * <p>
406	     * The national-number length (the digits after the country code) is additionally validated for
407	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
408	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
409	     *
410	     * @param telephone the raw telephone as submitted
411	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
412	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
413	     *         or its national-number length is wrong for its country code
414	     */
415	    private String normalizeTelephone(String telephone) {
416	        String raw = telephone == null ? "" : telephone.trim();
417	        boolean hasCountryCode = raw.startsWith("+");
418	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
419	        if (hasCountryCode) {
420	            cleaned = cleaned.substring(1);
421	        }
422	        String digits;
423	        if (hasCountryCode) {
424	            digits = cleaned;
425	        } else {
426	            if (cleaned.startsWith("0")) {
427	                cleaned = cleaned.substring(1);
428	            }
429	            digits = "61" + cleaned;
430	        }
431	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
432	            throw new InvalidTelephoneException(telephone);
433	        }
434	        return "+" + digits;
435	    }
436	
437	    /**
438	     * Checks the national-number length of an E.164 digit string against its country code for the
439	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
440	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
441	     *
442	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
443	     * @return {@code true} if the national-number length is acceptable for the country code
444	     */
445	    private boolean hasValidNationalLength(String digits) {
446	        if (digits.startsWith("61")) {
447	            return digits.length() - 2 == 9;
448	        }
449	        if (digits.startsWith("1")) {
450	            return digits.length() - 1 == 10;
451	        }
452	        return true;
453	    }
454	
455	    /**
456	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
457	     * multi-character top-level label. Deliberately lenient about the exact character set while still
458	     * rejecting values that are clearly not addresses (e.g. missing '@').
459	     */
460	    private static final java.util.regex.Pattern EMAIL_PATTERN =
461	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
462	
463	    /**
464	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
465	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
466	     * lower-cased email domain.
467	     */
468	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
469	        "mailinator.com", "tempmail.com", "guerrillamail.com");
470	
471	    /**
472	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
473	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
474	     * lower-cased before being stored and returned.
475	     *
476	     * @param email the raw email as submitted, may be {@code null}
477	     * @return the lower-cased email, or {@code null} when none was supplied
478	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
479	     */
480	    private String normalizeEmail(String email) {
481	        if (email == null || email.isBlank()) {
482	            return null;
483	        }
484	        String trimmed = email.trim();
485	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
486	            throw new InvalidEmailException(email);
487	        }
488	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
489	        String domain = normalized.substring(normalized.indexOf('@') + 1);
490	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
491	            throw new DisposableEmailException(email);
492	        }
493	        return normalized;
494	    }
495	
496	    /**
497	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
498	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
499	     * {@link Localities#region}) accepts any 4-digit postcode.
500	     */
501	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
502	        "NSW", new int[] {2000, 2099},
503	        "VIC", new int[] {3000, 3099},
504	        "QLD", new int[] {4000, 4099});
505	
506	    /**
507	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
508	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
509	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
510	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
511	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
512	     *
513	     * @param city the owner's city, used to derive the region whose range constrains the postcode
514	     * @param postcode the raw postcode as submitted, may be {@code null}
515	     * @return the postcode when supplied, or {@code null} when none was supplied
516	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
517	     *         out of range for the city's region
518	     */
519	    private String validatePostcode(String city, String postcode) {
520	        if (postcode == null || postcode.isBlank()) {
521	            return null;
522	        }
523	        if (!postcode.matches("[0-9]{4}")) {
524	            throw new InvalidPostcodeException(postcode);
525	        }
526	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
527	        if (range != null) {
528	            int value = Integer.parseInt(postcode);
529	            if (value < range[0] || value > range[1]) {
530	                throw new InvalidPostcodeException(postcode);
531	            }
532	        }
533	        return postcode;
534	    }
535	
536	    /**
537	     * Common street-type abbreviations expanded to their full word during address normalization.
538	     */
539	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
540	        "ST", "STREET",
541	        "RD", "ROAD",
542	        "AVE", "AVENUE");
543	
544	    /**
545	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
546	     * whitespace collapse to a single space, the value is upper-cased and common street-type
547	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
548	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
549	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
550	     * for every address comparison (household duplicate detection and the shared household id).
551	     *
552	     * @param address the raw address as submitted
553	     * @return the normalized address
554	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
555	     */
556	    private String normalizeAddress(String address) {
557	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
558	        if (collapsed.isEmpty()) {
559	            throw new InvalidAddressException(address);
560	        }
561	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
562	        StringBuilder normalized = new StringBuilder(collapsed.length());
563	        for (int i = 0; i < tokens.length; i++) {
564	            if (i > 0) {
565	                normalized.append(' ');
566	            }
567	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
568	        }
569	        return normalized.toString();
570	    }
571	
572	    /**
573	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
574	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
575	     * owners are duplicates when they share the same normalized telephone and the same normalized email
576	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
577	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
578	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
579	     * still match.
580	     * <p>
581	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
582	     * grouping, so two members of the same household with different telephones have different
583	     * identities and are both allowed. Only owners with the same telephone and email collide.
584	     *
585	     * @param owner the owner being created, with its telephone and email already normalized
586	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
587	     */
588	    private void rejectDuplicateIdentity(Owner owner) {
589	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
590	        boolean duplicate = this.clinicService.findAllOwners().stream()
591	            .anyMatch(existing -> identity.equals(
592	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
593	        if (duplicate) {
594	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
595	            throw new DuplicateIdentityException(
596	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
597	        }
598	    }
599	
600	    /**
601	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
602	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
603	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
604	     */
605	    private String personalIdentity(String telephone, String email) {
606	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
607	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
608	    }
609	
610	    /**
611	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
612	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
613	     * when its national-number length does not match its country code.
614	     */
615	    private String toE164OrNull(String telephone) {
616	        try {
617	            return normalizeTelephone(telephone);
618	        } catch (InvalidTelephoneException e) {
619	            return null;
620	        }
621	    }
622	
623	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
624	    @Override
625	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
626	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
627	        if (currentOwner == null) {
628	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
629	        }
630	        currentOwner.setAddress(ownerFieldsDto.getAddress());
631	        currentOwner.setCity(ownerFieldsDto.getCity());
632	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
633	        currentOwner.setLastName(ownerFieldsDto.getLastName());
634	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
635	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
636	        this.clinicService.saveOwner(currentOwner);
637	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
638	    }
639	
640	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
641	    @Transactional
642	    @Override
643	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
644	        Owner owner = this.clinicService.findOwnerById(ownerId);
645	        if (owner == null) {
646	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
647	        }
648	        this.clinicService.deleteOwner(owner);
649	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
650	    }
651	
652	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
653	    @Override
654	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
655	        Owner owner = this.clinicService.findOwnerById(ownerId);
656	        if (owner == null) {
657	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
658	        }
659	        HttpHeaders headers = new HttpHeaders();
660	        Pet pet = petMapper.toPet(petFieldsDto);
661	        owner.setId(ownerId);
662	        pet.setOwner(owner);
663	        pet.getType().setName(null);
664	        this.clinicService.savePet(pet);
665	        PetDto petDto = petMapper.toPetDto(pet);
666	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
667	            .buildAndExpand(pet.getId()).toUri());
668	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
669	    }
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
672	    @Override
673	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
674	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
675	        if (currentOwner != null) {
676	            Pet currentPet = this.clinicService.findPetById(petId);
677	            if (currentPet != null) {
678	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
679	                currentPet.setName(petFieldsDto.getName());
680	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
681	                this.clinicService.savePet(currentPet);
682	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
683	            }
684	        }
685	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
691	        HttpHeaders headers = new HttpHeaders();
692	        Visit visit = visitMapper.toVisit(visitFieldsDto);
693	        Pet pet = new Pet();
694	        pet.setId(petId);
695	        visit.setPet(pet);
696	        this.clinicService.saveVisit(visit);
697	        VisitDto visitDto = visitMapper.toVisitDto(visit);
698	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
699	            .buildAndExpand(visit.getId()).toUri());
700	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
701	    }
702	
703	
704	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
705	    @Override
706	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
707	        Owner owner = this.clinicService.findOwnerById(ownerId);
708	        if (owner != null) {
709	            Pet pet = owner.getPet(petId);
710	            if (pet != null) {
711	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
712	            }
713	        }
714	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
715	    }
716	}
